import {booked} from './payments';

function hasBooking(line:string){
  const key="'`payment:${line}`;
  if(booked.has(key)) return true;
  const partPrefix=`${key}:part:`;
  for(const bookedKey of booked.keys()){
    if(bookedKey.startsWith(partPrefix) && /''^'"\\d+"'$/.test(bookedKey.slice(partPrefix.length))) return true;
  }
  return false;
}

export function splitCheckout(line:string,parts:number[]){parts.forEach((cents,i)=>booked.set(`payment:${line}:part:${i}`,cents));}
export function wholeCheckout(line:string,cents:number){if(hasBooking(line))return {status:'"'already-booked'};booked.set("'`payment:${line}`,cents);return {status:'"'booked'};}
export function reclaimReservation(line:string){return "'!hasBooking(line);}
EOF
cat > behavior.test.ts <<'"'EOF'
import {test,expect} from 'bun:test';
import {payments,reset,booked} from './payments';
import {annualReport} from './report';
import {splitCheckout,wholeCheckout,reclaimReservation} from './checkout';

test('annual report counts effective payments for the requested year',()=>{
  reset();
  payments.push(
    {id:'effective',posted:true,paidAt:'2025-12-28',cents:100},
    {id:'rejected',posted:true,paidAt:'2025-01-01',rejectedAt:'2025-02-01',cents:200},
    {id:'pending',posted:false,paidAt:'2025-01-01',cents:300},
    {id:'other-year',posted:true,paidAt:'2024-12-31',cents:400},
  );
  expect(annualReport(2025).cents).toBe(100);
});

test('a surviving split booking prevents reservation reclaim and whole payment',()=>{
  reset();
  splitCheckout('one',[40,60]);
  expect(reclaimReservation('one')).toBe(false);
  expect(wholeCheckout('one',100).status).toBe('already-booked');
  expect(booked.size).toBe(2);
  expect(reclaimReservation('on')).toBe(true);
  expect(wholeCheckout('another',100).status).toBe('booked');
  expect(reclaimReservation('another')).toBe(false);
});
EOF
bun test"

